    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public PersonaFileStoryState? State { get; init; }

    [JsonPropertyName("details")]
    public required List<PersonaFileStoryDetail> Details { get; init; }
}

