public sealed record PersonaImportPlanInput;

/// <summary>
/// A character as a file: everything somebody would have to send to put this presenter on another
/// station, and nothing that belongs to the station it came from
/// </summary>
public sealed record PersonaFile
{
    /// <summary>What shape this is, so a file from a later build says so rather than being read wrongly. The shapes below are what an import actually validates; this is for the human reading the failure</summary>
    [JsonPropertyName("format")]
    public required string Format { get; init; }

    /// <summary>When it was exported, ISO-8601</summary>
    [JsonPropertyName("takenAt")]
    public required string TakenAt { get; init; }

    /// <summary>The station it was taken from. Provenance only: an import writes into whichever station it is running as, and the two need not match</summary>
    [JsonPropertyName("station")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Station { get; init; }

    [JsonPropertyName("personas")]
    public required List<PersonaFilePersona> Personas { get; init; }
}

/// <summary>
/// What importing actually did, with the plan it did it from.
///
/// All or nothing: a file whose import failed part-way leaves the station exactly as it was, on
/// `PUT /settings`' own rule. The preview is what stands between an operator and a surprise, so a
/// partial landing would be the one outcome nothing had described
/// </summary>
public sealed record PersonaImportResult
{
    /// <summary>What it decided to do, notices and all, so the answer carries its own explanation</summary>
    [JsonPropertyName("plan")]
    public required PersonaImportPlan Plan { get; init; }

    [JsonPropertyName("created")]
    public required long Created { get; init; }

    /// <summary>Characters whose sheet was rewritten. An update replaces the sheet and ADDS stories; it never deletes one the operator here wrote</summary>
    [JsonPropertyName("updated")]
    public required long Updated { get; init; }

    [JsonPropertyName("storiesWritten")]
    public required long StoriesWritten { get; init; }

    [JsonPropertyName("detailsWritten")]
    public required long DetailsWritten { get; init; }

    /// <summary>The roster as it now stands, on this file's own rule: every mutation answers the whole list, because more than the named row can change</summary>
    [JsonPropertyName("personas")]
    public required PersonaList Personas { get; init; }
}

